void dbHub_noteScriptRunning(void) {
    scriptRunCtx *ctx = scriptCurrentRunCtx();
    int running = 0;
    int timedout = 0;
    int eval_mode = 0;
    if (ctx != NULL) {
        running = 1;
        dbHub.script_run_count++;
        if (ctx->flags & SCRIPT_TIMEDOUT) {
            timedout = 1;
            dbHub.script_timedout++;
        }
        if (ctx->flags & SCRIPT_EVAL_MODE) {
            eval_mode = 1;
            dbHub.script_eval_mode++;
        }
        dbHub.script_flags = ctx->flags;
        dbHub.script_repl = ctx->repl_flags;
        dbHub.script_start = ctx->start_time;
    } else {
        dbHub.script_flags = 0;
        dbHub.script_repl = 0;
        dbHub.script_start = 0;
        dbHub.script_idle++;
    }
    dbHub.script_running = running;
    dbHub.script_is_timedout = timedout;
    dbHub.script_is_eval = eval_mode;
}

void dbHub_noteScriptCaller(void) {
    scriptRunCtx *ctx = scriptCurrentRunCtx();
    client *caller = NULL;
    client *engine = NULL;
    int caller_notouch = 0;
    int engine_notouch = 0;
    if (ctx != NULL) {
        caller = ctx->original_client;
        engine = ctx->c;
        if (caller != NULL) {
            dbHub.script_caller_id = caller->id;
            if (caller->flag.no_touch) {
                caller_notouch = 1;
                dbHub.script_caller_notouch_hits++;
            }
            if (caller->cmd != NULL && caller->cmd->proc == touchCommand) {
                dbHub.script_caller_touch_cmd++;
            }
        } else {
            dbHub.script_caller_id = 0;
        }
        if (engine != NULL) {
            dbHub.script_engine_id = engine->id;
            if (engine->flag.no_touch) {
                engine_notouch = 1;
                dbHub.script_engine_notouch_hits++;
            }
        } else {
            dbHub.script_engine_id = 0;
        }
    } else {
        dbHub.script_caller_id = 0;
        dbHub.script_engine_id = 0;
    }
    dbHub.script_caller_notouch = caller_notouch;
    dbHub.script_engine_notouch = engine_notouch;
}

void dbHub_noteExecutingClient(void) {
    client *exec = server.executing_client;
    client *cur = server.current_client;
    int diverge = 0;
    int exec_touch = 0;
    int cur_touch = 0;
    if (exec != NULL && exec->cmd != NULL && exec->cmd->proc == touchCommand) exec_touch = 1;
    if (cur != NULL && cur->cmd != NULL && cur->cmd->proc == touchCommand) cur_touch = 1;
    if (exec != cur) {
        diverge = 1;
        dbHub.script_client_diverge++;
    }
    dbHub.script_exec_touch = exec_touch;
    dbHub.script_cur_touch = cur_touch;
    dbHub.script_clients_diverge = diverge;
    dbHub.script_exec_id = exec ? exec->id : 0;
    dbHub.script_cur_id = cur ? cur->id : 0;
}

void dbHub_noteScriptTouchEligibility(void) {
    dbHub_noteScriptRunning();
    dbHub_noteScriptCaller();
    dbHub_noteExecutingClient();
    int allow_touch = 0;
    if (dbHub.script_exec_touch) {
        allow_touch = 1;
        dbHub.script_allow_touch++;
    } else if (!dbHub.script_running && dbHub.script_cur_touch) {
        allow_touch = 1;
        dbHub.script_allow_touch++;
    } else {
        dbHub.script_deny_touch++;
    }
    dbHub.script_touch_allowed = allow_touch;
}

